(() => {'use strict';const g=()=>window.gameDebug,$=id=>document.getElementById(id);
function locked(item){const a=g().active();if(g().busy||window.HUD?.pending||g().state.combat)return 'Дождитесь окончания движения или боя.';if(item.id.startsWith('gear')){const name=a.inventory[+item.id.slice(4)]||'';if(/броня|кольч|доспех|кожан/i.test(name))return 'Надетую броню пока нельзя передавать или выбрасывать.';if((/меч/.test(name)&&a.hands.includes('sword'))||(/щит/i.test(name)&&a.hands.includes('shield'))||(/посох|булава/.test(name)&&a.hands.includes('staff'))||(/лук/.test(name)&&a.hands.includes('bow')))return 'Сначала уберите этот предмет из рук.';return '';}if(item.id==='torch'){if(!a.torches)return 'Нет факелов.';if(a.hands.includes('torch')&&a.torches===1)return 'Сначала погасите и уберите факел.';return '';}if(item.id==='potion')return g().state.potions>0?'':'Нет зелий.';return 'Этот предмет связан с историей или не передаётся.';}
function take(item){if(locked(item))return null;const a=g().active();if(item.id.startsWith('gear')){const index=+item.id.slice(4);const name=a.inventory.splice(index,1)[0];return name?{name,itemType:'gear'}:null;}if(item.id==='torch'){a.torches--;return{name:'Факел',itemType:'torch'};}if(item.id==='potion'){g().state.potions--;return{name:'Лечебное зелье',itemType:'potion'};}return null;}
function drop(item){if(locked(item))return;if((g().state.drops||[]).length>=100){g().tell("Сначала подберите оставленные вещи.");g().render();return;}const a=g().active(),S=g().scene,candidates=[];for(let y=0;y<S.H;y++)for(let x=0;x<S.W;x++)if(!g().blocked({x,y})&&!g().props.some(p=>p.x===x&&p.y===y)&&!g().all().some(p=>p.x===x&&p.y===y)){const distance=Math.abs(x-a.x)+Math.abs(y-a.y);if(distance<=2)candidates.push({x,y,distance});}candidates.sort((a,b)=>a.distance-b.distance||a.y-b.y||a.x-b.x);if(!candidates.length){g().tell('Рядом нет свободной клетки для вещи.');g().render();return;}const data=take(item);if(!data)return;g().state.drops||=[];g().state.drops.push({...data,id:'drop-'+crypto.randomUUID(),scene:S.id,x:candidates[0].x,y:candidates[0].y});g().tell('Вы оставили «'+data.name+'» на полу. Вещь можно подобрать обратно.');g().save();g().render();}
function pickup(p){const drops=g().state.drops||[],i=drops.findIndex(d=>d.id===p.id);if(i<0)return;const d=drops[i];if(d.itemType==='gear'&&g().active().inventory.length>=100){g().tell('Рюкзак заполнен.');g().render();return;}if(d.itemType==='gear')g().active().inventory.push(d.name);else if(d.itemType==='torch')g().active().torches++;else if(d.itemType==='potion')g().state.potions++;drops.splice(i,1);g().tell('Подобрано: '+d.name+'.');g().save();g().render();}
function transfer(item){if(locked(item))return;const d=$('modal'),body=$('modal-body');$('modal-title').textContent='Передать предмет';body.replaceChildren();const npcs=g().props.filter(p=>p.type==='npc');if(!npcs.length){body.textContent='В этой комнате нет NPC. Подойдите в комнату с персонажем.';}for(const npc of npcs){const b=document.createElement('button');b.className='npc-transfer';const portrait=window.Artwork.npc(npc.name);const text=document.createElement('span');text.textContent=npc.name;b.append(portrait,text);b.onclick=async()=>{d.close();const ok=await g().approachTransfer(npc,()=>{const data=take(item);if(!data)return;g().state.npcGifts||=[];g().state.npcGifts.push(npc.id+': '+data.name);if(g().state.npcGifts.length>200)g().state.npcGifts.shift();g().tell('Вы передали «'+data.name+'» персонажу '+npc.name+'.');window.episodeDialogue('Спасибо, я сохраню эту вещь.',[{label:'Вернуться к карте',fn:window.closeDialogue}],npc.name,true);});if(!ok){g().tell('Передача отменена: нет свободного прохода или движение остановлено.');g().render();}};body.append(b);}d.showModal();}
function controls(item,host){if(!item.id.startsWith('gear')&&!['torch','potion'].includes(item.id))return;const reason=locked(item);for(const [text,fn,icon]of [['Выбросить',()=>drop(item),'bag'],['Передать NPC',()=>transfer(item),'hand']]){const b=document.createElement('button');b.className='inventory-action';b.textContent=text;b.disabled=!!reason;b.onclick=fn;window.UIIcons.apply(b,icon);host.append(b);}if(reason){const p=document.createElement('p');p.className='item-lock-note';p.textContent=reason;host.append(p);}}
window.Inventory={drop,pickup,transfer,controls,locked};})();
